head.script:
scwin.screenId = "jldstf75300";

///////// 1. 변수 및 선언 영역 /////////

scwin.isLoad = false;

scwin.relLawNo = "";

scwin.outputOrdNo = "";

scwin.index = "";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.pageIndex = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_usrLdMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "usrLdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrLdMktTpCd")) === '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "usrLdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrLdMktTpCd")) === '2'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "usrLdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrLdMktTpCd")) === '6'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) !== '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) !== '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) !== '1'); } }, { id: "if_usrTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) === '1'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_formatKeywrd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("formatKeywrd")))); } },
        { childId: "ipt_integSrchNo", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("integSrchNo")))); } },
        { childId: "ipt_searchRelLawNm", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchRelLawNm")))); } },
        { childId: "ipt_searchRelLawNm2", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchRelLawNm2")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_searchList();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75300.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf75300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

