/**
 * @method
 * @name scwin.searchTaskExp
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_integSrchNo
 * @returns
 * @hidden N
*/
scwin.searchTaskExp = function (ipt_integSrchNo) {
    /* sdd-asis-lifecycle:begin fn_searchTaskExp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_pageIndex2').setValue("1");
    $c.util.getComponent('ipt_integSrchNo').setValue(ipt_integSrchNo);
    scwin.openRelLaw(ipt_integSrchNo);
    if (!scwin.isLoad) {
        scwin.fn_searchRelLawDtl();
        scwin.isLoad = true;
    }
    $c.util.getComponent('editorArea').setStyle('display', 'block');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchKeyRelLaw
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchKeyRelLaw = function () {
    /* sdd-asis-lifecycle:begin fn_searchKeyRelLaw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
